import 'package:flutter/material.dart';
class TripHistoryPage extends StatelessWidget{const TripHistoryPage({super.key});@override Widget build(BuildContext context){const trips=[['جامعة سوهاج الجديدة','ميدان الثقافة','60 ج','مكتملة'],['محطة سوهاج','شارع الجمهورية','38 ج','مكتملة'],['الكوثر','جامعة سوهاج','—','ملغاة']];return Scaffold(backgroundColor:const Color(0xFFF6F1E8),appBar:AppBar(title:const Text('رحلاتي'),centerTitle:true),body:ListView.separated(padding:const EdgeInsets.all(18),itemCount:trips.length,separatorBuilder:(_,__)=>const SizedBox(height:10),itemBuilder:(_,i){final t=trips[i];return Container(padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:const Color(0xFFFFFBF5),borderRadius:BorderRadius.circular(20)),child:Column(crossAxisAlignment:CrossAxisAlignment.end,children:[Row(textDirection:TextDirection.rtl,children:[Expanded(child:Text(t[3],textDirection:TextDirection.rtl,style:TextStyle(color:t[3]=='ملغاة'?const Color(0xFF9A4B42):const Color(0xFF477A55),fontWeight:FontWeight.w800))),Text(t[2],style:const TextStyle(color:Color(0xFF171817),fontSize:17,fontWeight:FontWeight.w900))]),const SizedBox(height:12),_Line(Icons.my_location_rounded,t[0]),const SizedBox(height:8),_Line(Icons.location_on_rounded,t[1]) ]));}));}}
class _Line extends StatelessWidget{const _Line(this.icon,this.text);final IconData icon;final String text;@override Widget build(BuildContext context)=>Row(textDirection:TextDirection.rtl,children:[Icon(icon,size:17,color:const Color(0xFFB98B52)),const SizedBox(width:8),Expanded(child:Text(text,textDirection:TextDirection.rtl,textAlign:TextAlign.right,style:const TextStyle(color:Color(0xFF171817),fontSize:12)))]);}